ALTER TABLE "document_chunks" ADD COLUMN "structural_search_vector" "tsvector" GENERATED ALWAYS AS (setweight(to_tsvector('simple', lower(translate(coalesce("symbol_name", ''), '/._-', '    '))), 'A') || setweight(to_tsvector('simple', lower(translate(coalesce("path", ''), '/._-', '    '))), 'B') || setweight(to_tsvector('simple', lower(translate(coalesce("parent_symbol", ''), '/._-', '    '))), 'C') || setweight(to_tsvector('simple', coalesce("symbol_kind", '')), 'D')) STORED;--> statement-breakpoint
CREATE INDEX "document_chunks_structural_search_vector_gin_index" ON "document_chunks" USING gin ("structural_search_vector");--> statement-breakpoint
CREATE INDEX "document_chunks_repository_symbol_name_index" ON "document_chunks" USING btree ("repository_id","symbol_name");